mapper.select:
select fe.company_id from 
	fnd_employee fe     		
where  fe.employee_code = #{employeeCode,jdbcType=VARCHAR}

select DISTINCT em.employee_id as employeeId, em.employee_code as employeeCode, em.company_id as companyId, em.name as name, em.email as email, em.mobil as mobil, em.phone as phone, em.id_type as idType, em.id_card_no as idCardNo, em.enabled_flag as enabledFlag from fnd_employee em left join fnd_employee_assigns fea on em.employee_id = fea.employee_id left join fnd_org_position fop on fop.position_id = fea.position_id
em.enabled_flag = 'Y'
and em.employee_id = #{employeeId}
and em.employee_code like concat(concat('%',#{employeeCode}),'%')
and em.company_id = #{companyId}
and em.name like concat(concat('%',#{name}),'%')
and fop.position_id=#{positionId}
and em.name!=#{projectManagerName}

select fea.employee_assign_id, em.employee_id as employeeId, em.employee_code as employeeCode, em.company_id as companyId, em.name as name, em.email as email, em.mobil as mobil, em.phone as phone, em.id_type as idType, em.id_card_no as idCardNo, em.enabled_flag as enabledFlag, fou.unit_name as unit_name, fc.company_full_name as company_name, fou.unit_id as unit_id, ( select fe.name from fnd_employee fe, fnd_employee_assigns feas where fe.employee_id=feas.employee_id and feas.unit_id=fou.unit_id and feas.position_id=fop.position_id )as manager_name from fnd_employee em, fnd_employee_assigns fea, fnd_org_position fop, fnd_org_unit fou, fnd_company fc
em.employee_id=fea.employee_id and fou.unit_id = fea.unit_id and fop.position_id=fou.chief_position_id and fc.company_id=em.company_id
and em.employee_id = #{employeeId}
and em.employee_code like concat(concat('%',#{employeeCode}),'%')
and em.company_id = #{companyId}
and em.name like concat(concat('%',#{name}),'%')
and fop.position_id=#{positionId}
and em.name!=#{projectManagerName}
and fou.unit_type=#{unitType}
